// READ endpoint — projection: 3 columns, no tracking, COUNT in SQL
var cards = await db.Blogs
    .Where(b => b.IsPublic)
    .Select(b => new BlogCard(
        b.Id,
        b.Url,
        b.Posts.Count(p => p.PublishedAt != null)))
    .ToListAsync();
// SELECT b.Id, b.Url,
//        (SELECT COUNT(*) FROM Posts p WHERE p.BlogId = b.Id AND p.PublishedAt IS NOT NULL)
// FROM Blogs b WHERE b.IsPublic = 1

// Heavy Include graph → cartesian explosion risk
var blogs = await db.Blogs
    .Include(b => b.Posts)
    .ThenInclude(p => p.Comments)
    .Include(b => b.Authors)
    .ToListAsync();   // Posts × Comments × Authors rows in one result set

// Better when the graph is needed:
var blogs2 = await db.Blogs
    .Include(b => b.Posts).ThenInclude(p => p.Comments)
    .Include(b => b.Authors)
    .AsSplitQuery()          // one query per collection — bounded row sets
    .ToListAsync();

// EDIT endpoint — Include is correct: tracking lets SaveChanges diff the graph
var blog = await db.Blogs
    .Include(b => b.Posts)
    .FirstAsync(b => b.Id == id);
blog.Posts.Add(new Post { Title = "New" });  // tracked insert on save
await db.SaveChangesAsync();
